function status_badge(string $s): string { $m=['online'=>['success','ONLINE'],'offline'=>['secondary','OFFLINE'],'starting'=>['warning','STARTING'],'installing'=>['info','INSTALL'],'unreachable'=>['warning','CHECKING'],'failed'=>['danger','FAILED']];$v=$m[$s]??['secondary',strtoupper($s)];return '<span class="badge text-bg-'.$v[0].' status-badge">'.e($v[1]).'</span>'; }
function map_group(string $m): string { foreach(['de_'=>'DE — Bomb/Defuse','cs_'=>'CS — Hostage','zm_'=>'ZM — Zombie','fy_'=>'FY — Fight Yard','awp_'=>'AWP','aim_'=>'AIM','ka_'=>'KA — Knife','surf_'=>'SURF'] as $p=>$label){if(str_starts_with(strtolower($m),$p))return $label;}return 'Другие карты'; }
function map_options(array $maps,string $selected=''): string { $groups=[];foreach($maps as $m){$m=(string)$m;if(!preg_match('/^[A-Za-z0-9_-]{1,64}$/',$m))continue;$groups[map_group($m)][]=$m;} $out='';foreach($groups as $label=>$items){$out.='<optgroup label="'.e($label).'">';foreach($items as $m){$out.='<option value="'.e($m).'"'.($m===$selected?' selected':'').'>'.e($m).'</option>';}$out.='</optgroup>';}return $out; }
